        /// <summary>
        /// Restarted block GMRES(m) for a general (nonsymmetric) square A and s simultaneous
        /// right-hand sides, generic over BOTH the operator (<see cref="IfloatLinearOperator"/>) and
        /// the preconditioner (<see cref="IfloatPreconditioner"/>). Builds ONE shared block Krylov
        /// basis (block Arnoldi via <c>ApplyBlock</c>, modified block Gram-Schmidt with one
        /// reorthogonalization pass, deflating rank-revealing LQ per step -- active width w[j] &lt;= s,
        /// monotonically non-increasing within a restart cycle), minimizes the residual over that
        /// basis via a periodic dense QR re-solve of the accumulated block Hessenberg least-squares
        /// (not incremental block-Givens), and restarts every <paramref name="restart"/> block steps
        /// if the cycle has not converged. <paramref name="maxIter"/> counts TOTAL block steps across
        /// restarts, mirroring scalar <see cref="gmres{TOp, TPre}"/>.
        ///
        /// B and X are s ROWS x n COLS (row j = the j-th RHS/solution, length n = A.Rows; requires
        /// s &lt;= n, LQRP's own contract). X is warm-startable. Convergence is per column against
        /// tol²·‖B[j]‖², checked via the least-squares Pythagorean residual identity (no extra matvec).
        /// Owns its whole workspace via Allocator.Temp (no external scratch params, unlike bcg/bcgrq).
        /// Returns a <see cref="BlockSolveInfo"/> whose <see cref="BlockSolveInfo.minActive"/> is the
        /// smallest active search width reached over the whole solve (basis-rank deflation).
        /// </summary>
        public static BlockSolveInfo bgmres<TOp, TPre>(in TOp A, in TPre M, in floatMxN B, ref floatMxN X,
                                        int restart, int maxIter, float tol)
            where TOp : struct, IfloatLinearOperator
            where TPre : struct, IfloatPreconditioner
        {
            if (A.Rows != A.Cols) throw new ArgumentException("bgmres: A must be square");
            int n = A.Rows;
            int s = B.M_Rows;
            if (B.N_Cols != n) throw new ArgumentException("bgmres: B.N_Cols must equal A.Rows");
            if (X.M_Rows != s || X.N_Cols != n) throw new ArgumentException("bgmres: X must match B");
            if (restart < 1) throw new ArgumentException("bgmres: restart must be >= 1");
            if (maxIter < 1) throw new ArgumentException("bgmres: maxIter must be >= 1");
            if (s > n) throw new ArgumentException("bgmres: B.M_Rows (s) must be <= A.Rows");
            if (!M.IsConstant)
                throw new ArgumentException("Krylov.bgmres: requires a constant (non-flexible) preconditioner (M.IsConstant == false — e.g. an AMG K-cycle). Use the flexible variant (fcg / fgmres).");

            int m = restart;

            // Basis V[0..m], each s x n (dominant O(m s n) term). Wbuf/Tbuf/R0/Wcombo: s x n Arnoldi
            // and commit scratch. Zt/Zcombo/rowIn/rowOut: preconditioner scratch, allocated only for a
            // real M. Hbuf/Gbuf: the block-Hessenberg / least-squares accumulators (persist across the
            // whole cycle, true stride m*s / s). HQscratch/Rscratch/Yscratch/QtGscratch: the periodic
            // dense-QR re-solve's own working set, reused every inner step via RectView/RowsView.
            // Lbuf/HijBuf/YiBuf: small s x s GEMM/LQRP scratch.
            var V = new UnsafeList<floatMxN>(m + 1, Allocator.Temp);
            for (int i = 0; i <= m; i++) V.Add(new floatMxN(s, n, Allocator.Temp, true));

            // Wbuf is fed to LQRP.decomp as its "A" input via a RowsView narrower than Wbuf's true
            // s rows (w[j] <= s) -- LQRP internally computes a zero-threshold via Norms.LInf, which
            // reads the buffer's TRUE allocated length (Data.Length), not the view's logical row
            // count. Cleared so any such over-read sees zero, not uninitialized memory.
            var Wbuf   = new floatMxN(s, n, Allocator.Temp, false);
            var Tbuf   = new floatMxN(s, n, Allocator.Temp, true);
            var R0     = new floatMxN(s, n, Allocator.Temp, true);
            var Wcombo = new floatMxN(s, n, Allocator.Temp, true);

            floatMxN Zt = default, Zcombo = default;
            floatN rowIn = default, rowOut = default;
            if (!M.IsIdentity)
            {
                Zt     = new floatMxN(s, n, Allocator.Temp, true);
                Zcombo = new floatMxN(s, n, Allocator.Temp, true);
                rowIn  = new floatN(n);
                rowOut = new floatN(n);
            }

            var Hbuf = new floatMxN((m + 1) * s, m * s, Allocator.Temp, true);
            var Gbuf = new floatMxN((m + 1) * s, s, Allocator.Temp, true);

            // HQscratch is fed to QR.decompInPlace as its (in-place) "A_to_Q" input via a RectView
            // narrower than HQscratch's true m*s columns -- same Norms.LInf over-read risk as Wbuf
            // above. Cleared for the same reason.
            var HQscratch  = new floatMxN((m + 1) * s, m * s, Allocator.Temp, false);
            var Rscratch   = new floatMxN(m * s, m * s, Allocator.Temp, true);
            var Yscratch   = new floatMxN(m * s, s, Allocator.Temp, true);
            var QtGscratch = new floatMxN(m * s, s, Allocator.Temp, true);

            var Lbuf   = new floatMxN(s, s, Allocator.Temp, true);
            var HijBuf = new floatMxN(s, s, Allocator.Temp, true);
            var YiBuf  = new floatMxN(s, s, Allocator.Temp, true);

            var thr = new floatN(s);
            var w   = new Indices(m + 1, Allocator.Temp);
            var off = new Indices(m + 2, Allocator.Temp);

            // Per-column thresholds tol^2 ||B[j]||^2 (floored for zero/tiny-norm columns), computed once
            // (original RHS order -- rows never reordered here, unlike bcg/bcgrq's live-column permutation).
            BuildColumnThresholds(in B, ref thr, s, n, tol);

            IterativeSolveStatus status = IterativeSolveStatus.MaxIterations;
            int total = 0;
            int converged = 0;
            double maxr = 0;
            int minActive = s;

            while (total < maxIter)
            {
                // R0 = B - A X.
                BlockResidual(in A, in X, in B, ref R0, s, n);

                converged = CountConverged(in R0, in thr, s, n, out maxr);
                if (converged == s) { status = IterativeSolveStatus.Converged; break; }

                // Full reset of this cycle's block-Hessenberg / least-squares accumulators -- removes
                // any stale-buffer-from-a-previous-cycle risk when a later cycle's widths are smaller
                // than an earlier one's (Gbuf's row-groups >= 1 are never otherwise written).
                ZeroPrefix(ref Hbuf, (m + 1) * s, m * s);
                ZeroPrefix(ref Gbuf, (m + 1) * s, s);

                var Ppiv0 = new Pivot(s, Allocator.Temp);
                var L0 = View(Lbuf, s);
                var Q0 = V[0];   // LQRP decomposes directly into V[0]'s own s x n buffer
                LQRP.decomp(in R0, ref L0, ref Q0, ref Ppiv0);
                Ppiv0.Dispose();

                w[0] = LQRPRank(in L0, s, n);
                minActive = math.min(minActive, w[0]);
                if (w[0] == 0) { status = IterativeSolveStatus.Breakdown; break; }   // R0 != 0 yet rank 0 -- defensive

                off[0] = 0; off[1] = w[0];
                var V0 = RowsView(Q0, w[0]);
                var G0 = RowsView(Gbuf, w[0]);
                BlockCrossGram(in V0, in R0, ref G0);   // G0 = V0 R0^T -- R0 expressed in V0's basis

                // ---- inner block-Arnoldi loop: builds V[1..k], H's columns 0..k-1 ----
                int k = 0;
                bool cycleConverged = false;
                bool lsBreakdown = false;
                for (int j = 0; j < m && total < maxIter; j++)
                {
                    var Vj = RowsView(V[j], w[j]);
                    var Wj = RowsView(Wbuf, w[j]);
                    if (M.IsIdentity)
                    {
                        A.ApplyBlock(in Vj, ref Wj, w[j]);
                    }
                    else
                    {
                        var Ztj = RowsView(Zt, w[j]);
                        BlockApplyPre(in M, in Vj, ref Ztj, w[j], n, ref rowIn, ref rowOut);
                        A.ApplyBlock(in Ztj, ref Wj, w[j]);
                    }

                    int wj1 = BlockArnoldiMGS2Step(ref Wj, in V, ref w, ref off, ref Hbuf, ref HijBuf, ref Tbuf,
                                                    ref minActive, j, n);

                    total++;
                    k = j + 1;

                    // Least-squares solve (periodic dense re-QR of the accumulated Hbuf prefix) + a
                    // per-column residual check via the Pythagorean LS-residual identity -- no extra
                    // matvec, mirrors scalar gmres's O(1) per-step check.
                    cycleConverged = BlockLSResolveAndCheck(in Hbuf, in off, k, ref HQscratch, ref Rscratch,
                                                             ref Gbuf, ref Yscratch, ref QtGscratch, in thr, s,
                                                             out lsBreakdown);
                    if (lsBreakdown) break;

                    // Happy breakdown: the block Krylov subspace stopped growing -- the just-computed Y
                    // is already exact for the reachable subspace, so no further step can help.
                    if (cycleConverged || wj1 == 0) break;
                }

                if (lsBreakdown)
                {
                    // X was never updated this cycle -- the shared post-loop recompute below reports
                    // the TRUE fresh residual at the returned X, never this cycle's poisoned solve.
                    status = IterativeSolveStatus.Breakdown;
                    break;
                }

                // Commit: X += combine(Y, V[0..k-1]) -- k >= 1 always reached here (see the loop's own
                // invariant: total < maxIter held at cycle entry, so the for-loop body runs at least once).
                {
                    int totalCols = off[k];
                    var Yfinal = RowsView(Yscratch, totalCols);
                    ZeroPrefix(ref Wcombo, s, n);
                    for (int i = 0; i < k; i++)
                    {
                        var Yi = RectView(YiBuf, w[i], s);
                        CopyRowsFrom(in Yfinal, off[i], w[i], ref Yi);
                        var Vi = RowsView(V[i], w[i]);
                        var Ti = RowsView(Tbuf, s);
                        BlockCTV(in Yi, in Vi, ref Ti);
                        BlockAdd(ref Wcombo, in Ti, (float)1);
                    }
                    if (M.IsIdentity)
                    {
                        BlockAdd(ref X, in Wcombo, (float)1);
                    }
                    else
                    {
                        BlockApplyPre(in M, in Wcombo, ref Zcombo, s, n, ref rowIn, ref rowOut);
                        BlockAdd(ref X, in Zcombo, (float)1);
                    }
                }

                if (cycleConverged) { status = IterativeSolveStatus.Converged; break; }
                if (total >= maxIter) { status = IterativeSolveStatus.MaxIterations; break; }
                // else: loop back -- fresh restart, R0 recomputed from the just-updated X.
            }

            // Fresh residual from the final X (every BlockSolveInfo field is documented "at the
            // returned X") -- a cycle's top-of-loop CountConverged predates that cycle's own Commit.
            BlockResidual(in A, in X, in B, ref R0, s, n);
            converged = CountConverged(in R0, in thr, s, n, out maxr);
            if (status == IterativeSolveStatus.Converged && converged < s)
                status = IterativeSolveStatus.MaxIterations;

            for (int i = 0; i <= m; i++) V[i].Dispose();
            V.Dispose();
            Wbuf.Dispose(); Tbuf.Dispose(); R0.Dispose(); Wcombo.Dispose();
            if (!M.IsIdentity) { Zt.Dispose(); Zcombo.Dispose(); rowIn.Dispose(); rowOut.Dispose(); }
            Hbuf.Dispose(); Gbuf.Dispose();
            HQscratch.Dispose(); Rscratch.Dispose(); Yscratch.Dispose(); QtGscratch.Dispose();
            Lbuf.Dispose(); HijBuf.Dispose(); YiBuf.Dispose();
            thr.Dispose(); w.Dispose(); off.Dispose();

            return new BlockSolveInfo { rhs = s, converged = converged, iterations = total, maxRnorm = maxr, minActive = minActive, status = status };
        }

